/**
 * Loader for the static Quran word pool generated by
 * `scripts/generate-word-pool.ts`. Pool is split into two buckets:
 *   normal — frequently-occurring words (easier to recognize)
 *   zor    — rare or grammatically inflected forms
 */

import { useQuery } from "@tanstack/react-query";
import { useLocaleStore } from "~/stores/locale.store";
import { EMOJI_WORDS } from "./emoji-words";
import { WORD_PAIRS } from "./word-pairs";
import { WORD_GLOSS_ID } from "./indonesian-words";

export interface QuranWord {
  arabic: string;
  meaning: string;
}

interface PoolPayload {
  generatedAt: string;
  counts: { normal: number; zor: number; total: number };
  normal: QuranWord[];
  zor: QuranWord[];
}

export type WordPoolBucket = "normal" | "zor";

async function fetchPool(): Promise<PoolPayload> {
  const r = await fetch("/data/quran-word-pool.json");
  if (!r.ok) throw new Error("Failed to load word pool");
  return r.json();
}

export function useQuranWordPool() {
  const locale = useLocaleStore((s) => s.locale);
  return useQuery({
    queryKey: ["quran-word-pool", locale],
    queryFn: async () => {
      if (locale !== "id") return fetchPool();
      const normal = EMOJI_WORDS.filter((e) => WORD_GLOSS_ID[e.en]).map((e) => ({ arabic: e.arabic, meaning: WORD_GLOSS_ID[e.en] }));
      const zor = WORD_PAIRS.filter((e) => WORD_GLOSS_ID[e.meaningEn]).map((e) => ({ arabic: e.arabic, meaning: WORD_GLOSS_ID[e.meaningEn] }));
      return { generatedAt: "id", counts: { normal: normal.length, zor: zor.length, total: normal.length + zor.length }, normal, zor };
    },
    staleTime: Infinity,
  });
}

/** Map game-scoring difficulty to a word-pool bucket. */
export function bucketForDifficulty(d: "easy" | "medium" | "hard" | "hafiz"): WordPoolBucket {
  return d === "easy" || d === "medium" ? "normal" : "zor";
}
